const assert = require('node:assert/strict');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const crypto = require('node:crypto');
const { after, before, test } = require('node:test');
const { once } = require('node:events');
const { createApp } = require('../server');

// Commerce regression suite: intentionally credential-free so GitHub Actions can run it on every push.

const DESIGNER_TOKEN='designer-token-a', OTHER_TOKEN='designer-token-b', ADMIN_TOKEN='admin-token';
let server, context, baseUrl, tempDir;
before(async()=>{tempDir=fs.mkdtempSync(path.join(os.tmpdir(),'hob-commerce-'));context=createApp({dataDir:tempDir,seedProducts:[],designerTokens:{[DESIGNER_TOKEN]:'designer-a',[OTHER_TOKEN]:'designer-b'},adminToken:ADMIN_TOKEN,reviewRequired:true});server=context.app.listen(0,'127.0.0.1');await once(server,'listening');baseUrl='http://127.0.0.1:'+server.address().port;});
after(async()=>{if(server?.listening)await new Promise((resolve,reject)=>server.close(e=>e?reject(e):resolve()));context?.db.close();if(tempDir)fs.rmSync(tempDir,{recursive:true,force:true});});
async function json(route,options={}){const response=await fetch(baseUrl+route,options);let body={};try{body=await response.json();}catch{}return{response,body};}

test('Stripe paid webhook cannot change a canceled order or accept mismatched totals',async()=>{const dir=fs.mkdtempSync(path.join(os.tmpdir(),'hob-webhook-binding-'));let srv;let ctx;const previousSecret=process.env.STRIPE_WEBHOOK_SECRET;process.env.STRIPE_WEBHOOK_SECRET='whsec_binding_test';try{ctx=createApp({dataDir:dir,seedProducts:[],designerTokens:{},adminToken:ADMIN_TOKEN});const now=new Date().toISOString();ctx.db.prepare("INSERT INTO orders (id,stripe_session_id,status,currency,subtotal_cents,platform_fee_cents,designer_amount_cents,created_at) VALUES (?,?,?,?,?,?,?,?)").run('binding-order','cs_binding','pending','usd',10000,1000,9000,now);srv=ctx.app.listen(0,'127.0.0.1');await once(srv,'listening');const origin='http://127.0.0.1:'+srv.address().port;const send=async(session)=>{const event={id:'evt_'+Math.random(),type:'checkout.session.completed',data:{object:session}};const raw=JSON.stringify(event);const timestamp=Math.floor(Date.now()/1000);const sig=crypto.createHmac('sha256','whsec_binding_test').update(timestamp+'.'+raw).digest('hex');return fetch(origin+'/api/stripe/webhook',{method:'POST',headers:{'Content-Type':'application/json','Stripe-Signature':`t=${timestamp},v1=${sig}`},body:raw});};let response=await send({id:'cs_binding',metadata:{order_id:'binding-order'},payment_status:'paid',currency:'usd',amount_total:9999,payment_intent:'pi_wrong'});assert.equal(response.status,400);assert.equal(ctx.db.prepare('SELECT status FROM orders WHERE id=?').get('binding-order').status,'pending');ctx.db.prepare("UPDATE orders SET status='canceled' WHERE id='binding-order'").run();response=await send({id:'cs_binding',metadata:{order_id:'binding-order'},payment_status:'paid',currency:'usd',amount_total:10000,payment_intent:'pi_late'});assert.equal(response.status,409);assert.equal(ctx.db.prepare('SELECT status FROM orders WHERE id=?').get('binding-order').status,'canceled');}finally{if(previousSecret===undefined)delete process.env.STRIPE_WEBHOOK_SECRET;else process.env.STRIPE_WEBHOOK_SECRET=previousSecret;if(srv?.listening)await new Promise((resolve,reject)=>srv.close(e=>e?reject(e):resolve()));ctx?.db.close();fs.rmSync(dir,{recursive:true,force:true});}});

test('admin operations require admin credentials',async()=>{assert.equal((await json('/api/admin/operations')).response.status,401);assert.equal((await json('/api/admin/operations',{headers:{Authorization:'Bearer '+DESIGNER_TOKEN}})).response.status,403);});

test('seller orders isolate each designer',async()=>{const now=new Date().toISOString();context.db.prepare("INSERT INTO orders (id,status,currency,subtotal_cents,platform_fee_cents,designer_amount_cents,created_at,paid_at) VALUES (?,?,?,?,?,?,?,?)").run('isolation-order','paid','usd',10000,1000,9000,now,now);const insert=context.db.prepare("INSERT INTO order_items (id,order_id,listing_id,designer_id,title,unit_amount_cents,quantity,line_total_cents,platform_fee_cents,designer_amount_cents) VALUES (?,?,?,?,?,?,?,?,?,?)");insert.run('item-a','isolation-order','listing-a','designer-a','Private A',6000,1,6000,600,5400);insert.run('item-b','isolation-order','listing-b','designer-b','Private B',4000,1,4000,400,3600);const result=await json('/api/my/orders',{headers:{Authorization:'Bearer '+DESIGNER_TOKEN}});assert.equal(result.response.status,200);const order=result.body.orders.find(x=>x.id==='isolation-order');assert.ok(order);assert.deepEqual(order.items.map(x=>x.title),['Private A']);assert.equal(order.earningsCents,5400);});

test('paid orders cannot be canceled or inventory-released',async()=>{const headers={Authorization:'Bearer '+ADMIN_TOKEN};assert.equal((await json('/api/admin/orders/isolation-order/cancel',{method:'POST',headers})).response.status,409);assert.equal((await json('/api/admin/orders/isolation-order/inventory/release',{method:'POST',headers})).response.status,409);});

test('admin detail omits buyer email',async()=>{context.db.prepare("UPDATE orders SET buyer_email=? WHERE id=?").run('buyer@example.test','isolation-order');const result=await json('/api/admin/orders/isolation-order',{headers:{Authorization:'Bearer '+ADMIN_TOKEN}});assert.equal(result.response.status,200);assert.equal(Object.hasOwn(result.body.order,'buyer_email'),false);assert.deepEqual(result.body.items.map(x=>x.designer_id).sort(),['designer-a','designer-b']);});

test('tracking policy requires carrier movement',()=>{const source=fs.readFileSync(path.join(__dirname,'..','server.js'),'utf8');assert.match(source,/new Set\(\['in_transit','out_for_delivery','delivered','available_for_pickup'\]\)/);assert.doesNotMatch(source,/new Set\(\['pre_transit','in_transit'/);});

test('EasyPost webhook verifies HMAC v2 against exact raw body and freshness',()=>{const source=fs.readFileSync(path.join(__dirname,'..','server.js'),'utf8');const route=source.slice(source.indexOf("app.post('/api/easypost/webhook'"),source.indexOf("app.post('/api/stripe/webhook'"));assert.match(route,/express\.raw\(\{ type: 'application\/json'/);assert.match(route,/req\.get\('x-timestamp'\)/);assert.match(route,/req\.get\('x-path'\)/);assert.match(route,/req\.get\('x-hmac-signature-v2'\)/);assert.match(route,/timestamp \+ req\.method\.toUpperCase\(\) \+ signedPath/);assert.match(route,/crypto\.createHmac\('sha256', secret\)\.update\(stringToSign\)/);assert.match(route,/sentAt < now - 60_000/);assert.match(route,/sentAt > now \+ 30_000/);assert.ok(route.indexOf("createHmac('sha256'")<route.indexOf("JSON.parse(rawBody.toString('utf8'))"));assert.doesNotMatch(route,/JSON\.stringify\(req\.body\)/);assert.match(route,/description !== 'tracker\.updated'/);});

test('refund reverses transfers before refund and uses idempotency',()=>{const source=fs.readFileSync(path.join(__dirname,'..','server.js'),'utf8');const reversal=source.indexOf('/reversals');const refund=source.indexOf("stripeApi('refunds'");assert.ok(reversal>-1&&refund>reversal);assert.match(source,/hob-refund-reversal-/);assert.match(source,/hob-refund-/);});


test('Stripe checkout enables Stripe-managed promotion codes',()=>{const source=fs.readFileSync(path.join(__dirname,'..','server.js'),'utf8');const route=source.slice(source.indexOf("app.post('/api/checkout/session'"),source.indexOf("app.post('/api/checkout/cancel/:orderId'"));assert.match(route,/allow_promotion_codes: 'true'/);});

test('checkout status verification revalidates Stripe amount currency metadata and closed-order state',()=>{const server=fs.readFileSync(path.join(__dirname,'..','server.js'),'utf8');const route=server.slice(server.indexOf("app.get('/api/checkout/session/:sessionId'"),server.indexOf("app.get('/media/:imageId'"));assert.match(route,/session\.metadata\?\.order_id/);assert.match(route,/sessionTotal !== order\.subtotal_cents/);assert.match(route,/sessionCurrency !== String\(order\.currency\)\.toLowerCase\(\)/);assert.match(route,/order\.status === 'canceled' \|\| order\.status === 'failed'/);assert.ok(route.indexOf('sessionTotal !== order.subtotal_cents')<route.indexOf('UPDATE orders SET status = \'paid\''));});

test('checkout reserves inventory before Stripe and safely expires canceled sessions',()=>{const source=fs.readFileSync(path.join(__dirname,'..','server.js'),'utf8');const route=source.slice(source.indexOf("app.post('/api/checkout/session'"),source.indexOf("app.get('/api/gallery'"));assert.ok(route.indexOf('reserveInventory(orderId, quote.items, now)')<route.indexOf("stripeApi('checkout/sessions'"));assert.match(route,/idempotencyKey: `hob-checkout-\$\{orderId\}`/);assert.match(route,/catch \(error\) \{\s*\/\/ Never strand[\s\S]*releaseOrderInventory\(orderId\)/);assert.match(route,/checkout\/sessions\/\$\{encodeURIComponent\(order\.stripe_session_id\)\}\/expire/);assert.ok(route.indexOf('/expire')<route.lastIndexOf('releaseOrderInventory(order.id)'));});


test('checkout cancellation requires a separate hashed secret',()=>{const source=fs.readFileSync(path.join(__dirname,'..','server.js'),'utf8');const route=source.slice(source.indexOf("app.post('/api/checkout/session'"),source.indexOf("app.get('/api/gallery'"));assert.match(source,/ensureColumn\('orders', 'cancel_token_hash', 'TEXT'\)/);assert.match(route,/crypto\.randomBytes\(32\)\.toString\('base64url'\)/);assert.match(route,/crypto\.createHash\('sha256'\)\.update\(cancelToken\)\.digest\('hex'\)/);assert.match(route,/x-checkout-cancel-token/);assert.match(route,/safeEqual\(submittedHash, order\.cancel_token_hash\)/);assert.doesNotMatch(route,/res\.status\(201\)\.json\([^\n]*cancelToken/);});


test('designer payout notifications are outcome-specific and idempotent',()=>{const source=fs.readFileSync(path.join(__dirname,'..','server.js'),'utf8');assert.match(source,/ensureColumn\('designer_transfers', 'payout_success_notified_at', 'TEXT'\)/);assert.match(source,/ensureColumn\('designer_transfers', 'payout_failure_notified_at', 'TEXT'\)/);const notify=source.slice(source.indexOf('async function notifyPayout'),source.indexOf('async function stripeApi'));assert.match(notify,/if \(transfer\[column\]\) return false/);assert.match(notify,/Your House of Briar payout was sent/);assert.match(notify,/Your House of Briar payout needs attention/);assert.match(notify,/if \(sent\) db\.prepare/);const transfers=source.slice(source.indexOf('async function processDesignerTransfers'),source.indexOf('function releaseExpiredInventoryReservations'));assert.match(transfers,/await notifyPayout\(transferId, 'paid'\)/);assert.match(transfers,/await notifyPayout\(transferId, 'failed'\)/);assert.ok(transfers.indexOf("status = 'paid'")<transfers.indexOf("notifyPayout(transferId, 'paid')"));assert.ok(transfers.indexOf("status = 'failed'")<transfers.indexOf("notifyPayout(transferId, 'failed')"));});


test('OIDC discovery cannot send bearer tokens to a different origin',()=>{const server=fs.readFileSync(path.join(__dirname,'..','server.js'),'utf8');const resolver=server.slice(server.indexOf('async function resolveDesignerIdentity'),server.indexOf('async function authBuyer'));assert.match(resolver,/isSameOriginUrl\(metadata\.userinfo_endpoint, origin\)/);assert.ok(resolver.indexOf('isSameOriginUrl(metadata.userinfo_endpoint, origin)')<resolver.indexOf('Authorization: `Bearer ${token}`'));});

test('seller OIDC auth uses access tokens and explicit subject mapping',()=>{const server=fs.readFileSync(path.join(__dirname,'..','server.js'),'utf8');const account=fs.readFileSync(path.join(__dirname,'..','apps/default/src/pages/AccountPage.tsx'),'utf8');assert.match(account,/const sellerToken = auth\.user\?\.access_token \?\? ''/);assert.doesNotMatch(account,/const sellerToken = auth\.user\?\.id_token/);assert.match(server,/DESIGNER_IDENTITY_MAP_JSON/);const resolver=server.slice(server.indexOf('async function resolveDesignerIdentity'),server.indexOf('async function authDesigner'));assert.match(resolver,/metadata\.userinfo_endpoint/);const auth=server.slice(server.indexOf('async function authDesigner'),server.indexOf('function authAdmin'));assert.match(auth,/resolveDesignerIdentity\(req, token\)/);assert.match(auth,/designerIdentityMap\[subject\]/);assert.match(auth,/profile\.email_verified === true/);assert.match(auth,/designer_identities/);assert.match(auth,/designer_not_linked/);assert.doesNotMatch(auth,/req\.designerId = profile\.sub\.trim\(\)/);});


test('admin inventory release expires Stripe Checkout before freeing a piece',async()=>{const dir=fs.mkdtempSync(path.join(os.tmpdir(),'hob-admin-release-'));let srv;let ctx;const calls=[];try{ctx=createApp({dataDir:dir,seedProducts:[{id:'admin-release-piece',designerId:'designer-a',title:'Admin Release Piece',description:'test',price:55,category:'fashion'}],designerTokens:{[DESIGNER_TOKEN]:'designer-a'},adminToken:ADMIN_TOKEN,stripeApi:async(pathname,opts={})=>{calls.push({pathname,opts});if(pathname==='checkout/sessions')return{id:'cs_admin_release',url:'https://checkout.stripe.test/admin-release'};if(pathname==='checkout/sessions/cs_admin_release/expire')return{id:'cs_admin_release',status:'expired'};throw new Error('Unexpected Stripe path '+pathname);}});srv=ctx.app.listen(0,'127.0.0.1');await once(srv,'listening');const origin='http://127.0.0.1:'+srv.address().port;const checkout=await fetch(origin+'/api/checkout/session',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({items:[{id:'admin-release-piece',quantity:1}]})});const orderId=(await checkout.json()).orderId;const release=await fetch(origin+'/api/admin/orders/'+orderId+'/inventory/release',{method:'POST',headers:{Authorization:'Bearer '+ADMIN_TOKEN}});assert.equal(release.status,200);assert.ok(calls.some(x=>x.pathname==='checkout/sessions/cs_admin_release/expire'));assert.equal(ctx.db.prepare('SELECT status FROM orders WHERE id=?').get(orderId).status,'canceled');assert.equal(ctx.db.prepare('SELECT status FROM inventory_reservations WHERE listing_id=?').get('admin-release-piece').status,'released');}finally{if(srv?.listening)await new Promise((resolve,reject)=>srv.close(e=>e?reject(e):resolve()));ctx?.db.close();fs.rmSync(dir,{recursive:true,force:true});}});

test('an elapsed local reservation cannot be stolen while its Stripe Checkout Session may still exist',async()=>{const dir=fs.mkdtempSync(path.join(os.tmpdir(),'hob-reservation-authority-'));let srv;let ctx;let checkoutCalls=0;try{ctx=createApp({dataDir:dir,seedProducts:[{id:'reserved-piece',designerId:'designer-a',title:'Reserved Piece',description:'test',price:40,category:'fashion'}],designerTokens:{[DESIGNER_TOKEN]:'designer-a'},adminToken:ADMIN_TOKEN,stripeApi:async(pathname)=>{if(pathname==='checkout/sessions'){checkoutCalls++;return{id:'cs_reservation_'+checkoutCalls,url:'https://checkout.stripe.test/reservation'};}throw new Error('Unexpected Stripe path '+pathname);}});srv=ctx.app.listen(0,'127.0.0.1');await once(srv,'listening');const origin='http://127.0.0.1:'+srv.address().port;const first=await fetch(origin+'/api/checkout/session',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({items:[{id:'reserved-piece',quantity:1}]})});assert.equal(first.status,201);const firstBody=await first.json();ctx.db.prepare("UPDATE inventory_reservations SET expires_at='2000-01-01T00:00:00.000Z' WHERE order_id=?").run(firstBody.orderId);const second=await fetch(origin+'/api/checkout/session',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({items:[{id:'reserved-piece',quantity:1}]})});assert.equal(second.status,409);assert.equal(checkoutCalls,1);const reservation=ctx.db.prepare('SELECT order_id,status FROM inventory_reservations WHERE listing_id=?').get('reserved-piece');assert.equal(reservation.order_id,firstBody.orderId);assert.equal(reservation.status,'reserved');}finally{if(srv?.listening)await new Promise((resolve,reject)=>srv.close(e=>e?reject(e):resolve()));ctx?.db.close();fs.rmSync(dir,{recursive:true,force:true});}});

test('Stripe redirect origins use configured app origin and reject lookalike origins',async()=>{const dir=fs.mkdtempSync(path.join(os.tmpdir(),'hob-origin-'));let srv;let ctx;const calls=[];try{ctx=createApp({dataDir:dir,seedProducts:[{id:'origin-piece',designerId:'designer-a',title:'Origin Piece',description:'test',price:20,category:'fashion'}],designerTokens:{[DESIGNER_TOKEN]:'designer-a'},adminToken:ADMIN_TOKEN,appOrigin:'https://houseofbriar.example',stripeApi:async(pathname,opts={})=>{calls.push({pathname,opts});if(pathname==='checkout/sessions')return{id:'cs_origin',url:'https://checkout.stripe.test/origin'};throw new Error('Unexpected Stripe path '+pathname);}});srv=ctx.app.listen(0,'127.0.0.1');await once(srv,'listening');const origin='http://127.0.0.1:'+srv.address().port;const response=await fetch(origin+'/api/checkout/session',{method:'POST',headers:{'Content-Type':'application/json','Host':'attacker.example'},body:JSON.stringify({items:[{id:'origin-piece',quantity:1}]})});assert.equal(response.status,201);const checkout=calls.find(x=>x.pathname==='checkout/sessions');const params=new URLSearchParams(checkout.opts.body);assert.match(params.get('success_url'),/^https:\/\/houseofbriar\.example\//);assert.doesNotMatch(params.get('success_url'),/attacker\.example/);assert.equal((()=>{try{return new URL('https://houseofbriar.example.evil.test/account').origin===new URL('https://houseofbriar.example').origin}catch{return false}})(),false);}finally{if(srv?.listening)await new Promise((resolve,reject)=>srv.close(e=>e?reject(e):resolve()));ctx?.db.close();fs.rmSync(dir,{recursive:true,force:true});}});

test('suspending a designer revokes both linked OIDC and configured legacy-token access',async()=>{const dir=fs.mkdtempSync(path.join(os.tmpdir(),'hob-suspend-'));let srv;let ctx;try{ctx=createApp({dataDir:dir,seedProducts:[],designerTokens:{'legacy-suspended':'legacy-designer'},adminToken:ADMIN_TOKEN,resolveIdentity:async({token})=>token==='linked-suspended'?{sub:'suspended-subject',email:'suspended@example.test',email_verified:true}:null});const now=new Date().toISOString();ctx.db.prepare("INSERT INTO designer_profiles (id,email,display_name,brand_name,status,created_at) VALUES (?,?,?,?,?,?)").run('linked-designer','suspended@example.test','Suspended','Suspended Atelier','active',now);ctx.db.prepare("UPDATE designer_profiles SET email=?,display_name=?,brand_name=?,status=? WHERE id=?").run('legacy@example.test','Legacy','Legacy Atelier','suspended','legacy-designer');srv=ctx.app.listen(0,'127.0.0.1');await once(srv,'listening');const origin='http://127.0.0.1:'+srv.address().port;let r=await fetch(origin+'/api/my/designer-profile',{headers:{Authorization:'Bearer linked-suspended'}});assert.equal(r.status,200);ctx.db.prepare("UPDATE designer_profiles SET status='suspended' WHERE id='linked-designer'").run();r=await fetch(origin+'/api/my/designer-profile',{headers:{Authorization:'Bearer linked-suspended'}});assert.equal(r.status,403);assert.equal((await r.json()).error.code,'designer_inactive');r=await fetch(origin+'/api/my/designer-profile',{headers:{Authorization:'Bearer legacy-suspended'}});assert.equal(r.status,403);assert.equal((await r.json()).error.code,'designer_inactive');}finally{if(srv?.listening)await new Promise((resolve,reject)=>srv.close(e=>e?reject(e):resolve()));ctx?.db.close();fs.rmSync(dir,{recursive:true,force:true});}});

test('full commerce lifecycle preserves 90/10 split through payout and refund reversal',async()=>{const dir=fs.mkdtempSync(path.join(os.tmpdir(),'hob-lifecycle-'));const stripeCalls=[];const emails=[];let appServer;let lifecycle;try{const stripeApi=async(pathname,opts={})=>{stripeCalls.push({pathname,opts});if(pathname==='checkout/sessions'&&opts.method==='POST')return{id:'cs_test_lifecycle',url:'https://checkout.stripe.test/session'};if(pathname==='checkout/sessions/cs_test_lifecycle')return{id:'cs_test_lifecycle',status:'complete',payment_status:'paid',payment_intent:'pi_test_lifecycle',currency:'usd',amount_total:10000,metadata:{order_id:lifecycle.db.prepare("SELECT id FROM orders WHERE stripe_session_id='cs_test_lifecycle'").get()?.id},customer_details:{email:'buyer@example.test'}};if(pathname==='transfers')return{id:'tr_test_lifecycle'};if(pathname==='transfers/tr_test_lifecycle/reversals')return{id:'trr_test_lifecycle'};if(pathname==='refunds')return{id:'re_test_lifecycle',status:'succeeded'};throw new Error('Unexpected Stripe path '+pathname);};lifecycle=createApp({dataDir:dir,seedProducts:[{id:'lifecycle-piece',designerId:'designer-a',title:'Lifecycle Piece',description:'test',price:100,category:'fashion'}],designerTokens:{[DESIGNER_TOKEN]:'designer-a'},adminToken:ADMIN_TOKEN,connectAccounts:{'designer-a':'acct_test_designer'},stripeApi,verifyShipmentTracking:async(number,carrier)=>({verified:true,id:'trk_test_lifecycle',carrier,status:'in_transit'}),sendEmail:async(message)=>{emails.push(message);return true;},reviewRequired:true});appServer=lifecycle.app.listen(0,'127.0.0.1');await once(appServer,'listening');const origin='http://127.0.0.1:'+appServer.address().port;const call=async(route,options={})=>{const response=await fetch(origin+route,options);let body={};try{body=await response.json();}catch{}return{response,body};};const checkout=await call('/api/checkout/session',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({items:[{id:'lifecycle-piece',quantity:1}]})});assert.equal(checkout.response.status,201);lifecycle.db.prepare('UPDATE listings SET designer_email=? WHERE id=?').run('designer@example.test','lifecycle-piece');const order=lifecycle.db.prepare('SELECT * FROM orders WHERE id=?').get(checkout.body.orderId);assert.equal(order.subtotal_cents,10000);assert.equal(order.platform_fee_cents,1000);assert.equal(order.designer_amount_cents,9000);assert.equal(lifecycle.db.prepare('SELECT status FROM inventory_reservations WHERE order_id=?').get(order.id).status,'reserved');const paid=await call('/api/checkout/session/cs_test_lifecycle');assert.equal(paid.response.status,200);assert.equal(paid.body.paid,true);assert.equal(lifecycle.db.prepare('SELECT status FROM inventory_reservations WHERE order_id=?').get(order.id).status,'sold');let transfer=lifecycle.db.prepare('SELECT * FROM designer_transfers WHERE order_id=?').get(order.id);assert.equal(transfer.amount_cents,9000);assert.equal(transfer.status,'pending');const seller=await call('/api/my/orders',{headers:{Authorization:'Bearer '+DESIGNER_TOKEN}});assert.equal(seller.response.status,200);assert.equal(seller.body.orders.find(x=>x.id===order.id).earningsCents,9000);const tracking=await call('/api/orders/'+order.id+'/tracking',{method:'POST',headers:{Authorization:'Bearer '+DESIGNER_TOKEN,'Content-Type':'application/json'},body:JSON.stringify({carrier:'USPS',trackingNumber:'9400111899223856928499'})});assert.equal(tracking.response.status,200);assert.equal(tracking.body.verified,true);transfer=lifecycle.db.prepare('SELECT * FROM designer_transfers WHERE order_id=?').get(order.id);assert.equal(transfer.status,'paid');assert.equal(transfer.stripe_transfer_id,'tr_test_lifecycle');for(let attempt=0;attempt<20&&!transfer.payout_success_notified_at;attempt++){await new Promise(resolve=>setTimeout(resolve,5));transfer=lifecycle.db.prepare('SELECT * FROM designer_transfers WHERE order_id=?').get(order.id);}assert.ok(transfer.payout_success_notified_at);const refund=await call('/api/admin/orders/'+order.id+'/refund',{method:'POST',headers:{Authorization:'Bearer '+ADMIN_TOKEN}});assert.equal(refund.response.status,200);assert.equal(refund.body.status,'succeeded');const refunded=lifecycle.db.prepare('SELECT * FROM orders WHERE id=?').get(order.id);assert.equal(refunded.refund_status,'succeeded');assert.equal(refunded.stripe_refund_id,'re_test_lifecycle');transfer=lifecycle.db.prepare('SELECT * FROM designer_transfers WHERE order_id=?').get(order.id);assert.equal(transfer.stripe_reversal_id,'trr_test_lifecycle');const reversalIndex=stripeCalls.findIndex(x=>x.pathname==='transfers/tr_test_lifecycle/reversals');const refundIndex=stripeCalls.findIndex(x=>x.pathname==='refunds');assert.ok(reversalIndex>-1&&refundIndex>reversalIndex);assert.equal(stripeCalls.find(x=>x.pathname==='transfers').opts.idempotencyKey,'hob-transfer-'+order.id+'-designer-a');assert.equal(stripeCalls[reversalIndex].opts.idempotencyKey,'hob-refund-reversal-'+order.id+'-designer-a');assert.equal(stripeCalls[refundIndex].opts.idempotencyKey,'hob-refund-'+order.id);assert.ok(emails.some(x=>x.subject==='Your House of Briar payout was sent'));assert.ok(emails.some(x=>x.subject==='Your House of Briar refund'));}finally{if(appServer?.listening)await new Promise((resolve,reject)=>appServer.close(e=>e?reject(e):resolve()));lifecycle?.db.close();fs.rmSync(dir,{recursive:true,force:true});}});


