test('listing moderation requires review, records rejection reason, and only publishes after approval',async()=>{const create=await json('/api/listings',{method:'POST',headers:{Authorization:'Bearer '+DESIGNER_TOKEN,'Content-Type':'application/json'},body:JSON.stringify({title:'Moderated Piece',description:'Review me',price:125,category:'Accessories'})});assert.equal(create.response.status,201);const id=create.body.item.id;context.db.prepare("INSERT INTO listing_images (id,listing_id,client_image_key,storage_key,position,mime_type,size_bytes,width,height,checksum,upload_status,created_at) VALUES (?,?,?,?,0,'image/webp',1,1,1,'test','ready',?)").run('img-moderation',id,'image-key-moderation','test.webp',new Date().toISOString());const submitted=await json('/api/listings/'+id+'/submit',{method:'POST',headers:{Authorization:'Bearer '+DESIGNER_TOKEN,'Content-Type':'application/json'},body:JSON.stringify({marketplaceRulesAccepted:true})});assert.equal(submitted.response.status,200);assert.equal(submitted.body.item.status,'pending_review');assert.equal(submitted.body.item.moderationStatus,'pending');let gallery=await json('/api/gallery');assert.ok(!gallery.body.items.some(item=>item.id===id));const queue=await json('/api/admin/listings/review-queue',{headers:{Authorization:'Bearer '+ADMIN_TOKEN}});assert.equal(queue.response.status,200);assert.ok(queue.body.items.some(item=>item.id===id));const noReason=await json('/api/admin/listings/'+id+'/reject',{method:'POST',headers:{Authorization:'Bearer '+ADMIN_TOKEN,'Content-Type':'application/json'},body:'{}'});assert.equal(noReason.response.status,422);const rejected=await json('/api/admin/listings/'+id+'/reject',{method:'POST',headers:{Authorization:'Bearer '+ADMIN_TOKEN,'Content-Type':'application/json'},body:JSON.stringify({reason:'Please clarify materials.'})});assert.equal(rejected.response.status,200);assert.equal(rejected.body.item.moderationReason,'Please clarify materials.');const edited=await json('/api/listings/'+id,{method:'PUT',headers:{Authorization:'Bearer '+DESIGNER_TOKEN,'Content-Type':'application/json'},body:JSON.stringify({title:'Moderated Piece',description:'Materials clarified',price:125,category:'Accessories'})});assert.equal(edited.body.item.moderationReason,null);await json('/api/listings/'+id+'/submit',{method:'POST',headers:{Authorization:'Bearer '+DESIGNER_TOKEN,'Content-Type':'application/json'},body:JSON.stringify({marketplaceRulesAccepted:true})});const approved=await json('/api/admin/listings/'+id+'/approve',{method:'POST',headers:{Authorization:'Bearer '+ADMIN_TOKEN}});assert.equal(approved.response.status,200);gallery=await json('/api/gallery');assert.ok(gallery.body.items.some(item=>item.id===id));});

