test('buyer purchases are bound to authenticated OIDC subject',()=>{const server=fs.readFileSync(path.join(__dirname,'..','server.js'),'utf8');const account=fs.readFileSync(path.join(__dirname,'..','apps','default','src','pages','AccountPage.tsx'),'utf8');assert.match(server,/ensureColumn\('orders', 'buyer_subject', 'TEXT'\)/);assert.match(server,/WHERE o\.buyer_subject=\?/);assert.match(server,/app\.get\('\/api\/my\/purchases', authBuyer/);assert.match(server,/buyer_subject, buyer_email/);assert.match(account,/fetch\('\/api\/my\/purchases'/);assert.match(account,/Guest purchases are not linked by email for privacy/);});

test('account badges are server-awarded and buyer scoped',()=>{const server=fs.readFileSync(path.join(__dirname,'..','server.js'),'utf8');const account=fs.readFileSync(path.join(__dirname,'..','apps','default','src','pages','AccountPage.tsx'),'utf8');assert.match(server,/CREATE TABLE IF NOT EXISTS user_badges/);assert.match(server,/awardBadge\(order\.buyer_subject,'verified_buyer','order',order\.id\)/);assert.match(server,/WHERE buyer_subject=\?/);assert.match(server,/app\.get\('\/api\/my\/badges', authBuyer/);assert.doesNotMatch(server,/app\.post\('\/api\/my\/badges/);assert.match(account,/Verified Buyer/);assert.match(account,/Supporter/);});

test('donations use separate Stripe checkout and award supporter only after verified payment',()=>{const server=fs.readFileSync(path.join(__dirname,'..','server.js'),'utf8');const stripe=fs.readFileSync(path.join(__dirname,'..','apps','default','src','lib','stripe.ts'),'utf8');assert.match(server,/CREATE TABLE IF NOT EXISTS donations/);assert.match(server,/app\.post\('\/api\/donations\/session'/);assert.match(server,/amountCents<100\|\|amountCents>100000/);assert.match(server,/metadata\[donation_id\]/);assert.match(server,/total!==donation\.amount_cents/);assert.match(server,/awardBadge\(donation\.buyer_subject,'supporter','donation',donation\.id\)/);assert.match(stripe,/\/api\/donations\/session/);assert.doesNotMatch(stripe,/Donations are temporarily unavailable/);});

test('donation UI and history explain the five dollar supporter threshold',()=>{const home=fs.readFileSync(path.join(__dirname,'..','apps','default','src','pages','HomePage.tsx'),'utf8');const account=fs.readFileSync(path.join(__dirname,'..','apps','default','src','pages','AccountPage.tsx'),'utf8');const server=fs.readFileSync(path.join(__dirname,'..','server.js'),'utf8');assert.match(home,/\[5,10,25\]/);assert.match(home,/Donate \$5 or more while signed in to earn the Supporter badge/);assert.match(account,/\/api\/my\/donations/);assert.match(account,/Support history/);assert.match(server,/badgeEligible:row\.status==='paid'&&row\.amount_cents>=500/);});

test('public API hardening validates seller URLs, throttles sensitive flows, and preserves Studio server errors',()=>{const server=fs.readFileSync(path.join(__dirname,'..','server.js'),'utf8');const account=fs.readFileSync(path.join(__dirname,'..','apps','default','src','pages','AccountPage.tsx'),'utf8');assert.match(server,/validOptionalHttpUrl/);assert.match(server,/parsed\.protocol === 'https:' \|\| parsed\.protocol === 'http:'/);assert.match(server,/signupLimiter/);assert.match(server,/checkoutLimiter/);assert.match(server,/429, 'rate_limited'/);assert.match(account,/'checking' \| 'designer' \| 'signup' \| 'error'/);assert.match(account,/setStudioAccess\('error'\)/);assert.match(account,/Designer Studio is temporarily unavailable/);});

test('Designer Studio requires marketplace-rules confirmation before review submission',()=>{const account=fs.readFileSync(path.join(__dirname,'..','apps','default','src','pages','AccountPage.tsx'),'utf8');assert.match(account,/marketplaceRulesAccepted/);assert.match(account,/prohibited, counterfeit, stolen, dangerous, illegal/);assert.match(account,/disabled={!rulesAccepted\[product\.id\]}/);});


test('marketplace search controls and costumes category are wired end to end',()=>{const server=fs.readFileSync(path.join(__dirname,'..','server.js'),'utf8');const shop=fs.readFileSync(path.join(__dirname,'..','apps','default','src','pages','ShopPage.tsx'),'utf8');const marketplace=fs.readFileSync(path.join(__dirname,'..','apps','default','src','lib','marketplace.ts'),'utf8');assert.match(server,/['"]costumes['"]/);assert.match(marketplace,/['"]Costumes['"]/);assert.match(shop,/searchParams\.get\('q'\)/);assert.match(shop,/searchParams\.get\('category'\)/);assert.match(shop,/searchParams\.get\('price'\)/);assert.match(shop,/searchParams\.get\('sort'\)/);assert.match(shop,/price-low/);assert.match(shop,/price-high/);assert.match(shop,/Name: A to Z/);});

test('costumes is accepted as a listing category',async()=>{const created=await json('/api/listings',{method:'POST',headers:{Authorization:'Bearer '+DESIGNER_TOKEN,'Content-Type':'application/json'},body:JSON.stringify({title:'Moonlit Costume',description:'Wearable costume art',price:240,category:'costumes'})});assert.equal(created.response.status,201);assert.equal(created.body.item.category,'costumes');});


test('fresh listing schema includes style without relying on a follow-up migration',()=>{const server=fs.readFileSync(path.join(__dirname,'..','server.js'),'utf8');const schema=server.slice(server.indexOf('CREATE TABLE IF NOT EXISTS listings'),server.indexOf('CREATE TABLE IF NOT EXISTS designer_applications'));assert.match(schema,/category TEXT NOT NULL,\s*style TEXT,/);});

test('listing styles persist and power the buyer style window',async()=>{const created=await json('/api/listings',{method:'POST',headers:{Authorization:'Bearer '+DESIGNER_TOKEN,'Content-Type':'application/json'},body:JSON.stringify({title:'Boho Costume',description:'Style filter test',price:180,category:'costumes',style:'Boho'})});assert.equal(created.response.status,201);assert.equal(created.body.item.style,'Boho');const server=fs.readFileSync(path.join(__dirname,'..','server.js'),'utf8');const account=fs.readFileSync(path.join(__dirname,'..','apps','default','src','pages','AccountPage.tsx'),'utf8');const shop=fs.readFileSync(path.join(__dirname,'..','apps','default','src','pages','ShopPage.tsx'),'utf8');assert.match(server,/style: row\.style/);assert.match(account,/MARKET_STYLES/);assert.match(account,/>Style<select/);assert.match(shop,/Shop by style/);assert.match(shop,/searchParams\.get\('style'\)/);assert.match(shop,/matchesStyle/);});


test('designer storefront keeps Save button outside product navigation link',()=>{const page=fs.readFileSync(path.join(__dirname,'..','apps','default','src','pages','DesignerStorefrontPage.tsx'),'utf8');assert.match(page,/<article key=\{item\.id\}/);assert.doesNotMatch(page,/onClick=\{\(event\)=>\{event\.preventDefault\(\);toggleSaved/);});

test('buyer account stays usable while Designer Studio is checking or unavailable',()=>{const account=fs.readFileSync(path.join(__dirname,'..','apps','default','src','pages','AccountPage.tsx'),'utf8');const favoritesIndex=account.indexOf('const favoritesSection');const checkingIndex=account.indexOf("if (studioAccess === 'checking') return");const errorIndex=account.indexOf("if (studioAccess === 'error') return");assert.ok(favoritesIndex>0&&checkingIndex>favoritesIndex&&errorIndex>favoritesIndex);assert.match(account,/Your buyer account remains available while we check/);assert.match(account,/Your buyer account is still available/);});

test('production requires a fixed APP_ORIGIN instead of trusting the request Host header',()=>{const server=fs.readFileSync(path.join(__dirname,'..','server.js'),'utf8');assert.match(server,/process\.env\.NODE_ENV === 'production' && !configuredAppOrigin/);assert.match(server,/APP_ORIGIN must be configured in production/);assert.match(server,/parsedAppOrigin\.origin !== configuredAppOrigin/);});

test('production APP_ORIGIN must use HTTPS',()=>{const server=fs.readFileSync(path.join(__dirname,'..','server.js'),'utf8');assert.match(server,/APP_ORIGIN must use HTTPS in production/);assert.match(server,/new URL\(configuredAppOrigin\)\.protocol !== 'https:'/);});

test('buyer-only accounts keep purchases and saved pieces without requiring Designer Studio signup',()=>{const account=fs.readFileSync(path.join(__dirname,'..','apps','default','src','pages','AccountPage.tsx'),'utf8');const signupIndex=account.indexOf("if (studioAccess === 'signup') return");const favoritesIndex=account.indexOf('const favoritesSection');const purchasesIndex=account.indexOf('const purchasesSection');assert.ok(favoritesIndex>0&&purchasesIndex>0&&signupIndex>favoritesIndex&&signupIndex>purchasesIndex);assert.match(account,/Your buyer account is ready/);assert.match(account,/Designer tools are optional/);assert.match(account,/\/shop\?saved=true/);});

test('saved pieces refresh across account views and saved shop URLs use clear naming',()=>{const account=fs.readFileSync(path.join(__dirname,'..','apps','default','src','pages','AccountPage.tsx'),'utf8');const shop=fs.readFileSync(path.join(__dirname,'..','apps','default','src','pages','ShopPage.tsx'),'utf8');assert.match(account,/house-of-briar-saved-products/);assert.match(account,/refreshFavorites/);assert.match(shop,/searchParams\.get\('saved'\)/);assert.match(shop,/searchParams\.get\('liked'\)/);});


test('slug product pages use the canonical product id for saved and cart state',()=>{const page=fs.readFileSync(path.join(__dirname,'..','apps','default','src','pages','ProductPage.tsx'),'utf8');assert.match(page,/const resolvedProductId = product\?\.id/);assert.match(page,/getSavedProductIds\(\)\.includes\(resolvedProductId\)/);assert.match(page,/ids\.includes\(resolvedProductId\)/);assert.match(page,/value\.includes\(resolvedProductId\)/);});

test('product pages do not expose a hardcoded Loom Briar or personal contact email',()=>{const product=fs.readFileSync(path.join(__dirname,'..','apps','default','src','pages','ProductPage.tsx'),'utf8');assert.doesNotMatch(product,/geekgirl1039@gmail\.com/);assert.doesNotMatch(product,/designer === ['"]Loom Briar['"]/);assert.doesNotMatch(product,/mailto:/);assert.match(product,/InquiryForm productName=\{name\}/);});


test('checkout does not advertise or calculate unsupported local coupon discounts',()=>{const checkout=fs.readFileSync(path.join(__dirname,'..','apps','default','src','pages','CheckoutPage.tsx'),'utf8');const stripe=fs.readFileSync(path.join(__dirname,'..','apps','default','src','lib','stripe.ts'),'utf8');assert.doesNotMatch(checkout,/SAVE10/);assert.doesNotMatch(checkout,/couponInput|activeCoupon|discountAmount/);assert.doesNotMatch(stripe,/Promo codes are temporarily unavailable/);assert.match(checkout,/promotions available for this checkout are handled securely by Stripe/);assert.match(checkout,/money\.format\(subtotal\)/);});


test('every Designer Studio marketplace category is accepted by listing validation',async()=>{for(const category of ['one-of-a-kind','upcycled','vintage-inspired','handmade','botanical','limited edition','statement piece','costumes']){const created=await json('/api/listings',{method:'POST',headers:{Authorization:'Bearer '+DESIGNER_TOKEN,'Content-Type':'application/json'},body:JSON.stringify({title:'Category '+category,description:'Category compatibility test',price:25,category})});assert.equal(created.response.status,201,category);assert.equal(created.body.item.category,category);}});

